"use client";

// Prófunarkóðar: internal codes that make one purchase or one subscription
// period free, so staff can walk the real flow end to end — Medalia code
// from the pool, emails, booking — without a card.
//
// Each order or subscription paid with one is recorded as provider
// 'test_code' and never counted as revenue. Codes are generated by the
// server (TEST-XXXX-XXXX), single-use by default, and revoked rather than
// deleted so the record of who used what stays.
//
// API: /api/admin/hc/test-codes. Schema: supabase/migration-test-codes-straumur.sql

import { useCallback, useEffect, useState } from "react";
import { Copy, Loader2, Plus } from "lucide-react";
import { adminJson, adminErrorText } from "../hc-api";
import { useToast } from "@/app/components/hc/Toast";
import { fmtDate, fmtDateTime, useDialog } from "@/app/components/account/ui";

type Scope = "purchase" | "subscription" | "any";

interface TestCode {
  id: string;
  code: string;
  scope: Scope;
  package_key: string | null;
  single_use: boolean;
  used_by: string | null;
  used_by_email: string | null;
  used_at: string | null;
  use_count: number;
  expires_at: string | null;
  revoked_at: string | null;
  note: string | null;
  created_at: string;
}
interface Pkg { key: string; name: string; scope: "purchase" | "subscription" }

const SCOPE_IS: Record<Scope, string> = {
  purchase: "Kaup (skoðun, mæling, blóðprufa o.fl.)",
  subscription: "Áskrift (app eða þjálfun)",
  any: "Hvort tveggja",
};

function status(c: TestCode): { label: string; tone: string } {
  if (c.revoked_at) return { label: "Afturkallaður", tone: "bg-slate-100 text-slate-600" };
  if (c.single_use && c.used_at) return { label: "Notaður", tone: "bg-sky-50 text-sky-800" };
  if (c.expires_at && Date.parse(c.expires_at) <= Date.now()) return { label: "Útrunninn", tone: "bg-slate-100 text-slate-600" };
  return { label: "Ónotaður", tone: "bg-emerald-50 text-emerald-800" };
}

export default function TestCodesTab() {
  const toast = useToast();
  const { confirm } = useDialog();
  const [codes, setCodes] = useState<TestCode[] | null>(null);
  const [pkgs, setPkgs] = useState<Pkg[]>([]);
  const [loadErr, setLoadErr] = useState<string | null>(null);
  const [adding, setAdding] = useState(false);
  const [busy, setBusy] = useState<string | null>(null);
  const [err, setErr] = useState<string | null>(null);
  const [fresh, setFresh] = useState<string[]>([]);
  const [f, setF] = useState({ count: "10", scope: "purchase" as Scope, package_key: "", single_use: true, expires_at: "", note: "" });

  const load = useCallback(async () => {
    const r = await adminJson<{ codes: TestCode[]; packages: Pkg[] }>("/api/admin/hc/test-codes");
    setTimeout(() => {
      if (r.ok) { setCodes(r.data.codes ?? []); setPkgs(r.data.packages ?? []); setLoadErr(null); }
      else { setLoadErr(adminErrorText(r.error, "Ekki tókst að sækja prófunarkóða.")); setCodes((c) => c ?? []); }
    }, 0);
  }, []);
  useEffect(() => { void load(); }, [load]);

  const copy = async (text: string, what: string) => {
    try { await navigator.clipboard.writeText(text); toast.show(`${what} afritað`, { tone: "ok" }); }
    catch { toast.show("Ekki tókst að afrita. Veldu textann og afritaðu hann.", { tone: "bad" }); }
  };

  const create = async () => {
    setBusy("new"); setErr(null);
    const r = await adminJson<{ ok?: boolean; codes?: { code: string }[]; error?: string }>("/api/admin/hc/test-codes", {
      method: "POST",
      body: JSON.stringify({
        count: Number(f.count), scope: f.scope, package_key: f.package_key || null,
        single_use: f.single_use, expires_at: f.expires_at ? `${f.expires_at}T23:59:59` : null, note: f.note,
      }),
    });
    setBusy(null);
    if (!r.ok) { setErr(adminErrorText(r.error, "Kóðarnir urðu ekki til.")); return; }
    const made = (r.data.codes ?? []).map((c) => c.code);
    setFresh(made);
    setAdding(false);
    toast.show(`${made.length} ${made.length === 1 ? "kóði búinn til" : "kóðar búnir til"}`, { tone: "ok" });
    await load();
  };

  const revoke = async (c: TestCode) => {
    const ok = await confirm({
      title: `Afturkalla ${c.code}?`,
      body: "Kóðinn hættir strax að virka. Kaup sem þegar hafa verið gerð með honum standa.",
      confirmLabel: "Afturkalla", tone: "danger",
    });
    if (!ok) return;
    setBusy(c.id);
    const r = await adminJson("/api/admin/hc/test-codes", { method: "PATCH", body: JSON.stringify({ id: c.id, revoke: true }) });
    setBusy(null);
    if (!r.ok) toast.show(`Ekki tókst að afturkalla: ${adminErrorText(r.error)}`, { tone: "bad" });
    else toast.show(`${c.code} afturkallaður`, { tone: "ok" });
    await load();
  };

  if (codes === null) return <div className="h-32 animate-pulse rounded-xl bg-slate-100" aria-busy="true" />;
  const pkgName = (k: string | null) => (k ? pkgs.find((p) => p.key === k)?.name ?? k : "Allir pakkar");
  const pkgOptions = pkgs.filter((p) => f.scope === "any" || p.scope === f.scope);
  const unused = codes.filter((c) => status(c).label === "Ónotaður").length;

  return (
    <div className="space-y-4">
      {loadErr && (
        <div role="alert" className="rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">
          {loadErr} <button onClick={() => void load()} className="font-semibold underline">Reyna aftur</button>
        </div>
      )}
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <h2 className="text-lg font-bold text-slate-900">Prófunarkóðar</h2>
          <p className="max-w-2xl text-sm text-slate-600">
            Kóði gerir ein kaup eða einn áskriftarmánuð gjaldfrjálsan svo hægt sé að prófa allt ferlið: virkjunarkóða frá Medalia, tölvupósta og bókun.
            Slík kaup eru merkt „prófunarkóði“ og teljast ekki til tekna. {codes.length ? `${unused} ónotaðir af ${codes.length}.` : ""}
          </p>
        </div>
        {!adding && (
          <button type="button" onClick={() => { setAdding(true); setErr(null); }}
            className="inline-flex items-center gap-1.5 rounded-full bg-[#10B981] px-4 py-2 text-sm font-semibold text-white hover:bg-[#047857]">
            <Plus className="h-4 w-4" aria-hidden /> Búa til kóða
          </button>
        )}
      </div>

      {adding && (
        <div className="space-y-3 rounded-xl border border-slate-200 bg-white p-4">
          <div className="grid gap-3 sm:grid-cols-2">
            <label className="block text-sm">
              <span className="font-medium text-slate-700">Fjöldi</span>
              <input type="number" min={1} max={50} value={f.count} onChange={(e) => setF({ ...f, count: e.target.value })}
                className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-slate-900" />
            </label>
            <label className="block text-sm">
              <span className="font-medium text-slate-700">Gildir um</span>
              <select value={f.scope} onChange={(e) => setF({ ...f, scope: e.target.value as Scope, package_key: "" })}
                className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-slate-900">
                {(Object.keys(SCOPE_IS) as Scope[]).map((k) => <option key={k} value={k}>{SCOPE_IS[k]}</option>)}
              </select>
            </label>
            <label className="block text-sm">
              <span className="font-medium text-slate-700">Pakki</span>
              <select value={f.package_key} onChange={(e) => setF({ ...f, package_key: e.target.value })}
                className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-slate-900">
                <option value="">Allir pakkar</option>
                {pkgOptions.map((p) => <option key={p.key} value={p.key}>{p.name}</option>)}
              </select>
            </label>
            <label className="block text-sm">
              <span className="font-medium text-slate-700">Gildir til <span className="font-normal text-slate-500">(valfrjálst)</span></span>
              <input type="date" value={f.expires_at} onChange={(e) => setF({ ...f, expires_at: e.target.value })}
                className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-slate-900" />
            </label>
          </div>
          <label className="flex items-start gap-2 text-sm text-slate-700">
            <input type="checkbox" checked={f.single_use} onChange={(e) => setF({ ...f, single_use: e.target.checked })} className="mt-0.5 h-4 w-4 accent-[#047857]" />
            <span>Hver kóði virkar einu sinni <span className="text-slate-500">(mælt með; án haks má nota kóðann aftur og aftur þar til hann er afturkallaður)</span></span>
          </label>
          <label className="block text-sm">
            <span className="font-medium text-slate-700">Til hvers eru þeir?</span>
            <input value={f.note} onChange={(e) => setF({ ...f, note: e.target.value })} maxLength={200}
              placeholder="T.d. prófun á heilsufarsskoðun fyrir opnun"
              className="mt-1 w-full rounded-lg border border-slate-300 px-3 py-2 text-slate-900" />
          </label>
          {err && <p role="alert" className="text-sm text-red-600">{err}</p>}
          <div className="flex gap-2">
            <button type="button" onClick={() => void create()} disabled={busy === "new" || !(Number(f.count) >= 1)}
              className="inline-flex items-center gap-2 rounded-lg bg-[#10B981] px-4 py-2 text-sm font-semibold text-white disabled:opacity-50">
              {busy === "new" && <Loader2 className="h-4 w-4 animate-spin" aria-hidden />} Búa til
            </button>
            <button type="button" onClick={() => { setAdding(false); setErr(null); }}
              className="rounded-lg px-4 py-2 text-sm font-semibold text-slate-600 hover:bg-slate-100">Hætta við</button>
          </div>
        </div>
      )}

      {fresh.length > 0 && (
        <div className="rounded-xl border border-emerald-200 bg-emerald-50 p-4 text-sm">
          <div className="flex flex-wrap items-center justify-between gap-2">
            <p className="font-semibold text-emerald-900">Nýir kóðar</p>
            <button type="button" onClick={() => void copy(fresh.join("\n"), "Allir kóðarnir")}
              className="inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-semibold text-emerald-900 hover:bg-emerald-100">
              <Copy className="h-3.5 w-3.5" aria-hidden /> Afrita alla
            </button>
          </div>
          <p className="mt-2 select-all whitespace-pre-wrap font-mono text-emerald-950">{fresh.join("\n")}</p>
        </div>
      )}

      {codes.length > 0 && (
        <div className="overflow-x-auto rounded-xl border border-slate-200 bg-white">
          <table className="w-full text-sm">
            <thead className="border-b border-slate-200 bg-slate-50 text-left text-xs uppercase tracking-wide text-slate-500">
              <tr>
                <th className="p-3">Kóði</th><th className="p-3">Gildir um</th><th className="p-3">Staða</th>
                <th className="p-3">Gildir til</th><th className="p-3" />
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {codes.map((c) => {
                const s = status(c);
                return (
                  <tr key={c.id} className={s.label === "Ónotaður" ? "" : "bg-slate-50/60 text-slate-500"}>
                    <td className="p-3">
                      <span className="font-mono font-bold text-slate-900">{c.code}</span>
                      {!c.single_use && <span className="ml-2 rounded bg-amber-50 px-1.5 py-0.5 text-[11px] font-semibold text-amber-800">margnota</span>}
                      {c.note && <span className="mt-0.5 block text-xs text-slate-500">{c.note}</span>}
                    </td>
                    <td className="p-3">
                      {SCOPE_IS[c.scope].split(" (")[0]}
                      <span className="mt-0.5 block text-xs text-slate-500">{pkgName(c.package_key)}</span>
                    </td>
                    <td className="p-3">
                      <span className={`inline-flex rounded-full px-2 py-0.5 text-xs font-bold ${s.tone}`}>{s.label}</span>
                      {c.used_at && (
                        <span className="mt-0.5 block text-xs text-slate-500">
                          {c.single_use ? "af" : `${c.use_count}× · síðast`} {c.used_by_email ?? "óþekktum notanda"} {fmtDateTime(c.used_at)}
                        </span>
                      )}
                      {c.revoked_at && <span className="mt-0.5 block text-xs text-slate-500">{fmtDate(c.revoked_at)}</span>}
                    </td>
                    <td className="p-3">{c.expires_at ? fmtDate(c.expires_at) : "Ótímabundinn"}</td>
                    <td className="whitespace-nowrap p-3 text-right">
                      <button type="button" onClick={() => void copy(c.code, c.code)} aria-label={`Afrita ${c.code}`}
                        className="rounded-lg px-2 py-1.5 text-xs font-semibold text-slate-700 hover:bg-slate-100">
                        <Copy className="h-3.5 w-3.5" aria-hidden />
                      </button>
                      {!c.revoked_at && (
                        <button type="button" onClick={() => void revoke(c)} disabled={busy === c.id}
                          className="rounded-lg px-3 py-1.5 text-xs font-semibold text-red-700 hover:bg-red-50 disabled:opacity-50">
                          {busy === c.id ? "…" : "Afturkalla"}
                        </button>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
